/++
 + Synthetic throughput sweep for a 16 MiB Ant Farm.
 +
 +   make -C tools/perf run
 +   ./throughput --grid 8
 +   ldc2 -O2 -release throughput.d ../../antfarm/package.d ../../antfarm/allocation.d -of=throughput.exe
 +
 + Default mode searches topology, then payload/table shape, and prints a
 + ranked table. `--once` runs a single configuration (see README).
 + `--grid N` runs a single-phase small-producer grid (nb=0) across ns and
 + nc from 1 through N.
 + `--constant-header` replaces the PayloadEntry pool with the common-callback
 + write overload while keeping the same bodies, batches, and callbacks.
 + `--constant-callandlength` additionally supplies the uniform body length,
 + selecting arithmetic sizing without inspecting body fronts.
 + `--full-header-size` sizes the quota-fit check with the pre-compact
 + 16-word Callback, for runs against runtimes before SPEC 2f.
 + `--mixed-calls` alternates the PayloadEntry pool between two equivalent
 + callbacks, so every table has two Calls and is never uniform (SPEC 2g).
 +/
module throughput;
static if (__traits(compiles, PayloadHeader.init))
{
    enum legacy = true;
    alias BenchHeader = PayloadHeader;
}
else
{
    enum legacy = false;
    alias BenchHeader = Callback;
}

import antfarm;
import core.atomic;
import core.memory : GC;
import core.thread;
import core.time;
import core.stdc.stdio;
import core.stdc.stdlib : malloc, free, atoi, abort, strtoull;
import core.stdc.math : sqrt;

__gshared shared(long) g_calls;
__gshared shared(int) g_stop;
__gshared shared(int) g_ready;
__gshared bool g_globalCount;   // --global-count: old one-global-atomic callback
__gshared bool g_fullHeaderSize; // --full-header-size: pre-compact singleton sizing
__gshared bool g_mixedCalls;     // --mixed-calls: two Calls per PayloadEntry table

enum WriteMode : ubyte
{
    payloadEntry,
    constantHeader,
    constantCallAndLength,
}

// Per-worker batched counter.  The old single-global atomic increment made
// every Callback contend on one cache line (8 workers on one shared
// counter), so the sweep measured atomic-contention throughput rather than
// Ant Farm overhead.  Each worker accumulates locally and periodically
// flushes to the shared counter; the stop condition is still exact because
// consumers flush on idle and before unsubscribe.
//
// Function-local `static` is TLS in D (unlike C). A module-level mutable
// is also TLS, but a helper makes the storage duration obvious and gives
// one identity for increment + flush.
private enum uint LOCAL_FLUSH = 1024;

uint* workerCalls() nothrow @nogc @system
{
    static uint n;
    return &n;
}

static if (legacy)
{
static if (__traits(hasMember, PayloadHeader, "maxCs"))
{
long benchCbLocal(PayloadHeader* h, PayloadBody b, ulong iter) nothrow @nogc @system
{
    auto p = workerCalls();
    if (++(*p) >= LOCAL_FLUSH)
    {
        atomicFetchAdd(g_calls, cast(long) *p);
        *p = 0;
    }
    return 1;
}
}
else
{
long benchCbLocal(PayloadHeader* h, PayloadBody b) nothrow @nogc @system
{
    auto p = workerCalls();
    if (++(*p) >= LOCAL_FLUSH)
    {
        atomicFetchAdd(g_calls, cast(long) *p);
        *p = 0;
    }
    return 1;
}
}
}
else
{
extern(C) void benchCbLocal(const(ulong)* bodyPtr, size_t bodyWords) nothrow @nogc @system
{
    auto b = bodyPtr[0 .. bodyWords];
    auto p = workerCalls();
    if (++(*p) >= LOCAL_FLUSH)
    {
        atomicFetchAdd(g_calls, cast(long) *p);
        *p = 0;
    }
    return;
}
}

/// benchCbLocal's twin for --mixed-calls; a distinct function so tables that
/// alternate the two are not uniform.
static if (legacy)
{
static if (__traits(hasMember, PayloadHeader, "maxCs"))
{
long benchCbLocalAlt(PayloadHeader* h, PayloadBody b, ulong iter) nothrow @nogc @system
{
    auto p = workerCalls();
    if (++(*p) >= LOCAL_FLUSH)
    {
        atomicFetchAdd(g_calls, cast(long) *p);
        *p = 0;
    }
    return 2;
}
}
else
{
long benchCbLocalAlt(PayloadHeader* h, PayloadBody b) nothrow @nogc @system
{
    auto p = workerCalls();
    if (++(*p) >= LOCAL_FLUSH)
    {
        atomicFetchAdd(g_calls, cast(long) *p);
        *p = 0;
    }
    return 2;
}
}
}
else
{
extern(C) void benchCbLocalAlt(const(ulong)* bodyPtr, size_t bodyWords) nothrow @nogc @system
{
    auto b = bodyPtr[0 .. bodyWords];
    auto p = workerCalls();
    if (++(*p) >= LOCAL_FLUSH)
    {
        atomicFetchAdd(g_calls, cast(long) *p);
        *p = 0;
    }
    return;
}
}

static if (legacy)
{
static if (__traits(hasMember, PayloadHeader, "maxCs"))
{
long benchCbGlobal(PayloadHeader* h, PayloadBody b, ulong iter) nothrow @nogc @system
{
    atomicFetchAdd(g_calls, 1L);
    return 1;
}
}
else
{
long benchCbGlobal(PayloadHeader* h, PayloadBody b) nothrow @nogc @system
{
    atomicFetchAdd(g_calls, 1L);
    return 1;
}
}
}
else
{
extern(C) void benchCbGlobal(const(ulong)* bodyPtr, size_t bodyWords) nothrow @nogc @system
{
    auto b = bodyPtr[0 .. bodyWords];
    atomicFetchAdd(g_calls, 1L);
    return;
}
}

void flushLocalCalls() nothrow @nogc @system
{
    auto p = workerCalls();
    if (*p != 0)
    {
        atomicFetchAdd(g_calls, cast(long) *p);
        *p = 0;
    }
}

struct Cfg
{
    ulong ln = 1UL << 21;
    uint k = 8;
    uint nc = 4;
    uint nb = 1;
    uint ns = 0;
    uint body = 16;
    uint batch = 80;
    ulong n = 16_000_000;
    ulong qb = 0;      // 0 → segCap
    ulong qs = 4096;
    uint avgCost = DEFAULT_AVG_COST;  // chunk hint: MAX_CHUNK >> avgCost
    uint small = 64;   // small-table threshold; 0 = auto clamp(sq*chunk,16,256)
    uint repeats = 3;
    uint grid;   // --grid N: single-phase small-producer grid size
    bool huge;   // --huge: MADV_HUGEPAGE on the magic-buffer mapping
    WriteMode writeMode;
    bool nSet;
}

struct Trial
{
    Cfg cfg;
    double secs = 0;
    double mpps = 0;     // million payloads / s
    double mibs = 0;     // MiB/s of payload bodies
    ulong wt;
    uint stalls;
    bool ok;
    const(char)[] err;
}

struct ProdCtx
{
    AntFarm* f;
    PayloadEntry* pool;
    BenchHeader* commonCallback;
    PayloadBody* bodies;
    size_t poolN;
    size_t count;          // payloads this producer must commit
    Tier tier;
    uint batch;
    uint avgCost;          // chunk hint for write()
    uint bodyWords;
    WriteMode writeMode;
    shared uint* stalls;
    shared int* timedOut;
    MonoTime deadline;
}

struct ConsCtx
{
    AntFarm* f;
    long expected;
    MonoTime deadline;
    shared int* timedOut;
}

// Module-level classes (not function-nested): a nested class keeps `_outer`
// pointing at the creating stack frame.  Jobs live in a stable array and
// threads take `&jobs[i].run` so a loop-local cannot alias every worker to
// the last context (see tests/farm/torture_tests.d).
final class ProdJob
{
    ProdCtx* c;
    this(ProdCtx* c) { this.c = c; }
    void run() { producerMain(c); }
}

final class ConsJob
{
    ConsCtx* c;
    this(ConsCtx* c) { this.c = c; }
    void run() { consumerMain(c); }
}

void producerMain(ProdCtx* c)
{
    final switch (c.writeMode)
    {
    case WriteMode.payloadEntry:
        return producerMainImpl!(WriteMode.payloadEntry)(c);
    case WriteMode.constantHeader:
        return producerMainImpl!(WriteMode.constantHeader)(c);
    case WriteMode.constantCallAndLength:
        return producerMainImpl!(WriteMode.constantCallAndLength)(c);
    }
}

private void producerMainImpl(WriteMode writeMode)(ProdCtx* c)
{
    auto tok = c.f.registerProducer(c.tier);
    if (!tok.valid)
    {
        fprintf(stderr, "producer overregistration\n");
        abort();
    }
    ulong done;
    uint localStalls;
    while (done < c.count && atomicLoad(g_stop) == 0)
    {
        if (MonoTime.currTime > c.deadline)
        {
            atomicStore(*c.timedOut, 1);
            break;
        }
        immutable remain = c.count - done;
        immutable take = remain < c.batch ? remain : c.batch;
        immutable span = take < c.poolN ? take : c.poolN;
        static if (writeMode == WriteMode.constantHeader)
            immutable wrote = c.f.write(*c.commonCallback,
                c.bodies[0 .. span], tok, c.avgCost);
        else static if (writeMode == WriteMode.constantCallAndLength)
            immutable wrote = c.f.write(*c.commonCallback,
                c.bodies[0 .. span], c.bodyWords, tok, c.avgCost);
        else
            immutable wrote = c.f.write(c.pool[0 .. span], tok, c.avgCost);
        done += wrote;
        if (wrote == 0)
        {
            ++localStalls;
            Thread.yield();
        }
    }
    atomicOp!"+="(*c.stalls, localStalls);
    c.f.unregisterProducer(tok);
}

void consumerMain(ConsCtx* c)
{
    *workerCalls() = 0;
    ConsumerView v;
    if (v.subscribe(c.f) < 0)
    {
        fprintf(stderr, "subscribe failed\n");
        abort();
    }
    atomicFetchAdd(g_ready, 1);
    for (;;)
    {
        if (atomicLoad!(MemoryOrder.acq)(g_stop) != 0)
            break;
        if (!v.consumeNext())
        {
            flushLocalCalls();
            if (atomicLoad!(MemoryOrder.acq)(g_calls) >= c.expected)
                break;
            if (atomicLoad!(MemoryOrder.acq)(g_stop) != 0)
                break;
            if (MonoTime.currTime > c.deadline)
            {
                atomicStore(*c.timedOut, 1);
                break;
            }
            Thread.yield();
        }
    }
    flushLocalCalls();
    v.unsubscribe();
}

bool waitReady(int n, MonoTime deadline)
{
    while (atomicLoad!(MemoryOrder.acq)(g_ready) < n)
    {
        if (MonoTime.currTime > deadline)
            return false;
        Thread.yield();
    }
    return true;
}

/// Singleton table size for one ST payload; used to skip unsizable configs.
ulong singletonSize(uint body, uint sq)
{
    // THEAD 5 + 1 index + 7 pad + 1 progress + 7 pad + 8*sq Tcount + payload + 7 end
    // The bench's payloads are all ST, so the table is compact (SPEC 2f):
    // one Call word per record. --full-header-size restores the 16-word
    // legacy payload header for runs against pre-compact runtimes.
    return (legacy ? 8 : 5) + 1 + 7 + 1 + 7 + 8UL * sq + (g_fullHeaderSize ? 16 : 1) + body + 7;
}

bool cfgFits(ref const Cfg c)
{
    if (c.nb + c.ns == 0) return false;
    if (c.nc == 0 || c.nc > MAX_CONSUMERS_LIMIT) return false;
    immutable segCap = c.ln / c.k;
    immutable qb = c.qb == 0 ? segCap : c.qb;
    immutable exmax = cast(ulong) c.nb * qb + cast(ulong) c.ns * c.qs;
    if (exmax > (c.k - 1) * segCap) return false;
    immutable sq = sqcsOf(c.nc);
    immutable one = singletonSize(c.body, sq);
    if (c.nb && one > qb) return false;
    if (c.ns && one > c.qs) return false;
    return true;
}

Trial runOnce(Cfg c)
{
    Trial t;
    t.cfg = c;
    if (c.batch == 0)
    {
        t.err = "bad batch";
        return t;
    }
    if (c.body == 0)
    {
        t.err = "bad body";
        return t;
    }
    if (!cfgFits(c))
    {
        t.err = "skip (quota/Exmax)";
        return t;
    }

    immutable segCap = c.ln / c.k;
    // create() defaults quotaBulk==0 to segCap only when the bulk tier is
    // in use (nb > 0), so an unused bulk tier cannot inject a segCap quota
    // into the Exmax check; pass the configured value straight through.
    immutable qb = c.qb;
    auto f = AntFarm.create(ringMiBFromUlongs(c.ln), c.k, c.nc, c.nb, qb, c.ns, c.qs, c.small, c.huge);

    immutable poolN = c.batch < 256 ? 256 : c.batch;
    auto callbacks = cast(BenchHeader*) malloc(2 * BenchHeader.sizeof);
    auto body = cast(ulong*) malloc(c.body * ulong.sizeof);
    auto entries = cast(PayloadEntry*) malloc(poolN * PayloadEntry.sizeof);
    auto bodies = cast(PayloadBody*) malloc(poolN * PayloadBody.sizeof);
    if (callbacks is null || body is null || entries is null || bodies is null)
    {
        t.err = "alloc";
        if (callbacks) free(callbacks);
        if (body) free(body);
        if (entries) free(entries);
        if (bodies) free(bodies);
        f.destroy();
        return t;
    }
    static if (legacy)
    {
        callbacks[0] = PayloadHeader.init;
        static if (__traits(hasMember, PayloadHeader, "maxCs"))
        {
            callbacks[0].maxCs = 1;
            callbacks[0].done = 1;
        }
        callbacks[0].call = g_globalCount ? &benchCbGlobal : &benchCbLocal;
        callbacks[1] = callbacks[0];
        callbacks[1].call = &benchCbLocalAlt;
    }
    else
    {
    *callbacks = Callback.init;

    callbacks[0] = g_globalCount ? &benchCbGlobal : &benchCbLocal;
    callbacks[1] = callbacks[0];
    callbacks[1] = &benchCbLocalAlt;
    }
    foreach (i; 0 .. c.body)
        body[i] = i;
    foreach (i; 0 .. poolN)
    {
        static if (legacy)
            entries[i].header = callbacks + (g_mixedCalls && (i & 1) ? 1 : 0);
        else
            entries[i].call = callbacks[g_mixedCalls && (i & 1) ? 1 : 0];
        entries[i].body = body[0 .. c.body];
        bodies[i] = body[0 .. c.body];
    }

    immutable np = c.nb + c.ns;
    auto pctx = cast(ProdCtx*) malloc(np * ProdCtx.sizeof);
    auto cctx = cast(ConsCtx*) malloc(c.nc * ConsCtx.sizeof);
    if (pctx is null || cctx is null)
    {
        t.err = "context alloc";
        if (pctx) free(pctx);
        if (cctx) free(cctx);
        free(callbacks);
        free(body);
        free(entries);
        free(bodies);
        f.destroy();
        return t;
    }
    Thread[] producers = new Thread[np];
    Thread[] consumers = new Thread[c.nc];

    shared uint stalls;
    shared int timedOut;
    atomicStore(g_calls, 0L);
    atomicStore(g_stop, 0);
    atomicStore(g_ready, 0);
    atomicStore(stalls, 0);
    atomicStore(timedOut, 0);

    immutable expected = cast(long) c.n;
    auto deadline = MonoTime.currTime + 90.seconds;

    // Split the payload count across producers (bulk first, then small).
    // write() copies into the farm, so every producer reuses the same pool.
    size_t cursor;
    foreach (i; 0 .. np)
    {
        immutable remain = cast(size_t) c.n - cursor;
        immutable share = remain / (np - i);
        pctx[i] = ProdCtx(f, entries, callbacks, bodies, poolN, share,
                          i < c.nb ? Tier.bulk : Tier.small,
                          c.batch, c.avgCost, c.body, c.writeMode,
                          &stalls, &timedOut, deadline);
        cursor += share;
    }
    foreach (i; 0 .. c.nc)
        cctx[i] = ConsCtx(f, expected, deadline, &timedOut);

    auto prodJobs = new ProdJob[](np);
    auto consJobs = new ConsJob[](c.nc);

    GC.collect();
    GC.minimize();
    GC.disable();
    // Subscribe before the first write so tables see the live Cf/SqCs
    // rather than the Cf==0 fallback, and so a producer cannot lap an
    // unsubscribed farm.
    foreach (i; 0 .. c.nc)
    {
        consJobs[i] = new ConsJob(&cctx[i]);
        consumers[i] = new Thread(&consJobs[i].run);
        consumers[i].start();
    }
    if (!waitReady(cast(int) c.nc, MonoTime.currTime + 5.seconds))
    {
        atomicStore(g_stop, 1);
        foreach (cons; consumers)
            if (cons !is null)
                cons.join();
        GC.enable();
        free(pctx);
        free(cctx);
        free(callbacks);
        free(body);
        free(entries);
        free(bodies);
        f.destroy();
        t.err = "subscribe timeout";
        return t;
    }

    immutable t0 = MonoTime.currTime;
    foreach (i; 0 .. np)
    {
        prodJobs[i] = new ProdJob(&pctx[i]);
        producers[i] = new Thread(&prodJobs[i].run);
        producers[i].start();
    }
    foreach (p; producers)
        p.join();
    foreach (cons; consumers)
        cons.join();
    immutable t1 = MonoTime.currTime;
    GC.enable();

    immutable secs = (t1 - t0).total!"nsecs" / 1e9;
    immutable calls = atomicLoad(g_calls);
    t.secs = secs;
    t.wt = atomicLoad(f.Wt);
    t.stalls = atomicLoad(stalls);

    free(pctx);
    free(cctx);
    free(callbacks);
    free(body);
    free(entries);
    free(bodies);
    f.destroy();

    if (atomicLoad(timedOut) || calls != expected)
    {
        t.err = atomicLoad(timedOut) ? "TIMEOUT" : "lost work";
        return t;
    }
    t.ok = true;
    t.mpps = (c.n / secs) / 1e6;
    t.mibs = (cast(double) c.n * c.body * 8.0 / secs) / (1024.0 * 1024.0);
    return t;
}

Trial runMedian(Cfg c)
{
    Trial[8] rs;
    if (c.repeats == 0 || c.repeats > rs.length)
    {
        rs[0].cfg = c;
        rs[0].err = "repeats must be 1..8";
        return rs[0];
    }
    uint n;
    foreach (r; 0 .. c.repeats)
    {
        if (n >= rs.length) break;
        rs[n++] = runOnce(c);
        if (!rs[n - 1].ok && rs[n - 1].err != "skip (quota/Exmax)")
            return rs[n - 1];
        if (!rs[n - 1].ok)
            return rs[n - 1];
    }
    if (n == 0)
        return rs[0];

    // median by mpps
    foreach (i; 0 .. n)
        foreach (j; i + 1 .. n)
            if (rs[j].mpps < rs[i].mpps)
            {
                auto tmp = rs[i];
                rs[i] = rs[j];
                rs[j] = tmp;
            }
    return rs[n / 2];
}

void printHeader()
{
    printf("%-3s %3s %3s %3s %5s %5s %10s  %7s %8s %8s %8s  %s\n",
           "K".ptr, "nc".ptr, "nb".ptr, "ns".ptr, "body".ptr, "bat".ptr,
           "N".ptr, "sec".ptr, "Mpps".ptr, "MiB/s".ptr, "stalls".ptr, "note".ptr);
}

void printRow(ref const Trial t)
{
    auto c = t.cfg;
    if (!t.ok)
    {
        printf(" %-2u %3u %3u %3u %5u %5u %10llu  %7s %8s %8s %8s  %.*s\n",
               c.k, c.nc, c.nb, c.ns, c.body, c.batch, cast(ulong) c.n,
               "-".ptr, "-".ptr, "-".ptr, "-".ptr,
               cast(int) t.err.length, t.err.ptr);
        return;
    }
    printf(" %-2u %3u %3u %3u %5u %5u %10llu  %7.3f %8.3f %8.1f %8u\n",
           c.k, c.nc, c.nb, c.ns, c.body, c.batch, cast(ulong) c.n,
           t.secs, t.mpps, t.mibs, t.stalls);
}

Cfg parseArgs(string[] args, Cfg base)
{
    Cfg c = base;
    for (size_t i = 1; i < args.length; ++i)
    {
        auto a = args[i];
        if (a == "--once" || a == "--sweep")
            continue;
        if (a == "--global-count")
        {
            g_globalCount = true;
            continue;
        }
        if (a == "--full-header-size")
        {
            g_fullHeaderSize = true;
            continue;
        }
        if (a == "--mixed-calls")
        {
            g_mixedCalls = true;
            continue;
        }
        if (a == "--constant-header")
        {
            c.writeMode = WriteMode.constantHeader;
            continue;
        }
        if (a == "--constant-callandlength" ||
            a == "--constant-call-and-length")
        {
            c.writeMode = WriteMode.constantCallAndLength;
            continue;
        }
        if (a == "--huge")
        {
            c.huge = true;
            continue;
        }
        if (i + 1 >= args.length)
            break;
        auto v = args[++i];
        if (a == "--ln") c.ln = strtoull(v.ptr, null, 0);
        else if (a == "--k") c.k = cast(uint) atoi(v.ptr);
        else if (a == "--nc") c.nc = cast(uint) atoi(v.ptr);
        else if (a == "--nb") c.nb = cast(uint) atoi(v.ptr);
        else if (a == "--ns") c.ns = cast(uint) atoi(v.ptr);
        else if (a == "--body") c.body = cast(uint) atoi(v.ptr);
        else if (a == "--batch") c.batch = cast(uint) atoi(v.ptr);
        else if (a == "--n") { c.n = strtoull(v.ptr, null, 0); c.nSet = true; }
        else if (a == "--qb") c.qb = strtoull(v.ptr, null, 0);
        else if (a == "--qs") c.qs = strtoull(v.ptr, null, 0);
        else if (a == "--ac") c.avgCost = cast(uint) atoi(v.ptr);
        else if (a == "--small") c.small = cast(uint) atoi(v.ptr);
        else if (a == "--repeats") c.repeats = cast(uint) atoi(v.ptr);
        else if (a == "--grid") c.grid = cast(uint) atoi(v.ptr);
        else
            --i;
    }
    return c;
}

void scaleN(ref Cfg c)
{
    if (c.nSet) return;
    // Keep large-body runs from becoming a memcpy bench that takes minutes,
    // and give tiny bodies enough iterations that startup is not the signal.
    if (c.body >= 1024) c.n = 800_000;
    else if (c.body >= 256) c.n = 2_000_000;
    else if (c.body >= 64) c.n = 6_000_000;
    else c.n = 16_000_000;
}

void banner(ref const Cfg c)
{
    immutable bytes = c.ln * 8.0 / (1024.0 * 1024.0);
    printf("Ant Farm throughput  Ln=%llu (%.1f MiB)  repeats=%u  callback=%s  write=%s  huge=%s\n",
           cast(ulong) c.ln, bytes, c.repeats,
           g_mixedCalls ? "mixed-two-calls".ptr :
               (g_globalCount ? "global-atomic".ptr : "per-worker-batched".ptr),
           c.writeMode == WriteMode.payloadEntry ? "payload-entry".ptr :
               (c.writeMode == WriteMode.constantHeader ?
                    "constant-header".ptr : "constant-callandlength".ptr),
           c.huge ? "yes".ptr : "no".ptr);
    fflush(stdout);
}

int runGrid(Cfg base, uint gridN)
{
    if (gridN == 0 || gridN > MAX_CONSUMERS_LIMIT)
    {
        fprintf(stderr, "grid must be in 1..%u\n", MAX_CONSUMERS_LIMIT);
        return 1;
    }

    banner(base);
    printf("\n== phase 1: small-producer grid nb=0, ns/nc 1..%u (body=%u batch=%u) ==\n",
           gridN, base.body, base.batch);
    printHeader();

    Trial[] results;
    Trial best;
    best.mpps = -1;

    foreach (ns; 1 .. gridN + 1)
        foreach (nc; 1 .. gridN + 1)
        {
            Cfg c = base;
            c.nb = 0;
            c.ns = ns;
            c.nc = nc;
            scaleN(c);
            auto t = runMedian(c);
            printRow(t);
            fflush(stdout);
            if (t.ok)
            {
                results ~= t;
                if (t.mpps > best.mpps)
                    best = t;
            }
        }

    if (results.length == 0)
    {
        printf("grid produced no successful runs\n");
        return 1;
    }

    // Aggregate across all successful topologies. Each topology contributes
    // its repeated-run median Mpps as the representative throughput.
    double sum = 0;
    double sumSq = 0;
    foreach (r; results)
    {
        sum += r.mpps;
        sumSq += r.mpps * r.mpps;
    }
    immutable n = results.length;
    immutable aggMean = sum / n;
    double aggStddev = 0;
    if (n > 1)
    {
        immutable variance = (sumSq - sum * sum / n) / (n - 1);
        aggStddev = variance > 0 ? sqrt(variance) : 0;
    }

    double[] vals;
    foreach (r; results)
        vals ~= r.mpps;
    foreach (i; 0 .. n)
        foreach (j; i + 1 .. n)
            if (vals[j] < vals[i])
            {
                auto tmp = vals[i];
                vals[i] = vals[j];
                vals[j] = tmp;
            }
    immutable aggMedian = vals[n / 2];

    printf("\nbest small-producer grid: nc=%u ns=%u  %.3f Mpps  %.1f MiB/s\n",
           best.cfg.nc, best.cfg.ns, best.mpps, best.mibs);
    printf("grid aggregate: %llu topologies  mean=%.3f Mpps  stddev=%.3f Mpps  median=%.3f Mpps\n",
           cast(ulong) n, aggMean, aggStddev, aggMedian);
    fflush(stdout);
    return 0;
}

int runSweep(Cfg base)
{
    banner(base);
    printf("\n== phase 1: topology (body=%u batch=%u) ==\n", base.body, base.batch);
    printHeader();

    enum uint[] ks = [4, 8];
    enum uint[] ncs = [1, 2, 4, 8];
    struct Mix { uint nb, ns; }
    Mix[4] mixes = [Mix(1, 0), Mix(2, 0), Mix(1, 4), Mix(0, 4)];

    Trial[] results;
    Trial best;
    best.mpps = -1;

    foreach (k; ks)
        foreach (nc; ncs)
            foreach (mix; mixes)
            {
                Cfg c = base;
                c.k = k;
                c.nc = nc;
                c.nb = mix.nb;
                c.ns = mix.ns;
                scaleN(c);
                auto t = runMedian(c);
                printRow(t);
                fflush(stdout);
                if (t.ok)
                {
                    results ~= t;
                    if (t.mpps > best.mpps)
                        best = t;
                }
            }

    if (best.mpps < 0)
    {
        printf("phase 1 produced no successful runs\n");
        return 1;
    }

    printf("\nphase 1 winner: K=%u nc=%u nb=%u ns=%u  %.3f Mpps  %.1f MiB/s\n",
           best.cfg.k, best.cfg.nc, best.cfg.nb, best.cfg.ns,
           best.mpps, best.mibs);

    printf("\n== phase 2: body x batch on the winning topology ==\n");
    printHeader();

    enum uint[] bodies = [2, 16, 64, 256, 1024];
    enum uint[] batches = [1, 8, 16, 32, 63, 64, 80, 128, 256];

    Trial best2 = best;
    Trial bestBytes = best;

    foreach (body; bodies)
        foreach (batch; batches)
        {
            Cfg c = best.cfg;
            c.body = body;
            c.batch = batch;
            c.n = base.n;
            c.repeats = base.repeats;
            scaleN(c);
            auto t = runMedian(c);
            printRow(t);
            fflush(stdout);
            if (t.ok)
            {
                results ~= t;
                if (t.mpps > best2.mpps)
                    best2 = t;
                if (t.mibs > bestBytes.mibs)
                    bestBytes = t;
            }
        }

    printf("\n== ranked (successful runs, by Mpps) ==\n");
    printHeader();
    foreach (i; 0 .. results.length)
        foreach (j; i + 1 .. results.length)
            if (results[j].mpps > results[i].mpps)
            {
                auto tmp = results[i];
                results[i] = results[j];
                results[j] = tmp;
            }
    immutable show = results.length < 15 ? results.length : 15;
    foreach (i; 0 .. show)
        printRow(results[i]);

    printf("\nbest payloads/s : K=%u nc=%u nb=%u ns=%u body=%u batch=%u  %.3f Mpps  %.1f MiB/s\n",
           best2.cfg.k, best2.cfg.nc, best2.cfg.nb, best2.cfg.ns,
           best2.cfg.body, best2.cfg.batch, best2.mpps, best2.mibs);
    printf("best payload MiB/s: K=%u nc=%u nb=%u ns=%u body=%u batch=%u  %.3f Mpps  %.1f MiB/s\n",
           bestBytes.cfg.k, bestBytes.cfg.nc, bestBytes.cfg.nb, bestBytes.cfg.ns,
           bestBytes.cfg.body, bestBytes.cfg.batch, bestBytes.mpps, bestBytes.mibs);
    printf("phase-1 topology  : K=%u nc=%u nb=%u ns=%u  (held fixed in phase 2)\n",
           best.cfg.k, best.cfg.nc, best.cfg.nb, best.cfg.ns);
    fflush(stdout);
    return 0;
}

void main(string[] args)
{
    bool once;
    foreach (a; args[1 .. $])
        if (a == "--once")
            once = true;

    Cfg base;
    base = parseArgs(args, base);
    scaleN(base);

    if (base.grid > 0)
    {
        auto rc = runGrid(base, base.grid);
        if (rc != 0)
            abort();
        return;
    }
    if (once)
    {
        banner(base);
        printHeader();
        auto t = runMedian(base);
        printRow(t);
        if (!t.ok)
        {
            fprintf(stderr, "run failed: %.*s\n",
                    cast(int) t.err.length, t.err.ptr);
            abort();
        }
        return;
    }
    auto rc = runSweep(base);
    if (rc != 0)
        abort();
}
